-- Macros: totals for the full recipe, summed from its ingredients.
update public.recipes r
set kcal = t.kcal, protein_g = t.protein_g, carbs_g = t.carbs_g, fat_g = t.fat_g
from (
  select ri.recipe_id,
    sum(ri.grams * i.kcal_per_100g / 100)     as kcal,
    sum(ri.grams * i.protein_per_100g / 100)  as protein_g,
    sum(ri.grams * i.carbs_per_100g / 100)    as carbs_g,
    sum(ri.grams * i.fat_per_100g / 100)      as fat_g
  from public.recipe_ingredients ri
  join public.ingredients i on i.id = ri.ingredient_id
  group by ri.recipe_id
) t
where t.recipe_id = r.id;
